    if h.path not in paths:
        paths.append(h.path)
out = {}
for p in sorted(paths):
    out[p] = repo.read(p)
owners = repo.search("owner", glob="**")
result({
    "files": out,
    "src_listing": repo.list("src"),
    "root_listing": repo.list("."),
